# -*- coding: utf-8 -*-
from taf.fdsw.rc.clients.websocket.jsilib.jsilib_client import JSILIBClient
from taf.fdsw.rc.interfaces.fdsw import FDSW
from taf.fdsw.rc.interfaces.FDSW18SP.security import Security18SP
from taf.fdsw.rc.interfaces.FDSW20B.autoconnection import AutoConfiguration20B
from taf.fdsw.rc.interfaces.FDSW20B.diagnostics import Diagnostics20B
from taf.fdsw.rc.interfaces.FDSW20B.swm import SoftwareManagement20B


class FDSW20B(FDSW):
    VERSION_NAME = 'FDSW20B'
    _client = None

    def __init__(self, ip_address, port, username, password, secure):

        self._client = JSILIBClient(
            ip_address=ip_address,
            port=port,
            username=username,
            password=password,
        )

        self._client.connect()
        self.swm = SoftwareManagement20B(client=self._client)
        self.security = Security18SP(client=self._client)
        self.autoconnection = AutoConfiguration20B(client=self._client)
        self.diagnostics = Diagnostics20B(client=self._client)

    def disconnect(self):
        self.swm.clear_sw_update_cache()
        self._client.disconnect()
